/** Walk to the table at `parts`, creating the tables on the way. */
function descend(root, parts, path) {
  let node = root
  let walked = [...path]
  for (const part of parts) {
    walked = [...walked, part]
    let held = node.value.get(part)
    if (held === undefined) {
      held = table()
      node.value.set(part, held)
    }
    if (held.type === 'tables') held = held.value[held.value.length - 1]
    else if (held.type !== 'table') throw new ConfError(`${walked.join('.')} is not a table`)
    node = held
  }
  return node
}

